import React, { useState, useEffect } from 'react';
import { View, Text, StatusBar, SafeAreaView, TouchableOpacity, ScrollView, ActivityIndicator, Alert } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';
import api from '../../services/api';
import { useNavigation } from '@react-navigation/native';

const Container = styled.View`
  flex: 1;
  background-color: ${colors.background};
`;

const MapPlaceholder = styled.View`
  flex: 1;
  background-color: #f0f0f0;
  justify-content: center;
  align-items: center;
`;

const TopBar = styled.View`
  position: absolute;
  top: ${spacing.xl + 10}px;
  left: ${spacing.md}px;
  right: ${spacing.md}px;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  z-index: 10;
`;

const IconButton = styled.TouchableOpacity`
  width: 45px;
  height: 45px;
  border-radius: ${borderRadius.full}px;
  background-color: ${colors.white};
  justify-content: center;
  align-items: center;
  elevation: 5;
  shadow-color: #000;
  shadow-offset: 0px 2px;
  shadow-opacity: 0.15;
  shadow-radius: 4px;
`;

const BottomSheet = styled.View`
  background-color: ${colors.white};
  border-top-left-radius: 25px;
  border-top-right-radius: 25px;
  padding-top: ${spacing.sm}px;
  elevation: 25;
  shadow-color: #000;
  shadow-offset: 0px -10px;
  shadow-opacity: 0.1;
  shadow-radius: 15px;
  min-height: ${props => props.expanded ? '450px' : 'auto'};
`;

const Handle = styled.View`
  width: 40px;
  height: 5px;
  background-color: #e0e0e0;
  border-radius: 3px;
  align-self: center;
  margin-vertical: ${spacing.sm}px;
`;

const ContentPadding = styled.View`
  padding-horizontal: ${spacing.lg}px;
  padding-bottom: ${spacing.xl}px;
`;

const Greeting = styled.Text`
  font-size: 20px;
  font-weight: bold;
  color: ${colors.text};
  margin-bottom: 4px;
`;

const SearchButton = styled.TouchableOpacity`
  background-color: ${colors.background};
  border-radius: ${borderRadius.lg}px;
  height: 55px;
  flex-direction: row;
  align-items: center;
  padding-horizontal: ${spacing.md}px;
  margin-top: ${spacing.md}px;
  border-width: 1px;
  border-color: ${colors.border};
`;

const SearchButtonText = styled.Text`
  color: ${colors.textSecondary};
  font-size: 16px;
  flex: 1;
  margin-left: ${spacing.sm}px;
`;

const CategoryItem = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding-vertical: ${spacing.md}px;
  border-bottom-width: 1px;
  border-bottom-color: #f5f5f5;
  opacity: ${props => props.selected ? 1 : 0.7};
  background-color: ${props => props.selected ? '#fcfdfc' : 'transparent'};
`;

const CategoryLeft = styled.View`
  width: 60px;
  height: 40px;
  justify-content: center;
  align-items: center;
`;

const CategoryInfo = styled.View`
  flex: 1;
  margin-horizontal: ${spacing.sm}px;
`;

const CategoryName = styled.Text`
  font-size: 16px;
  font-weight: bold;
  color: ${colors.text};
`;

const CategoryTime = styled.Text`
  font-size: 12px;
  color: ${colors.textSecondary};
`;

const CategoryPrice = styled.Text`
  font-size: 16px;
  font-weight: bold;
  color: ${colors.text};
`;

const SelectIndicator = styled.View`
  width: 20px;
  height: 20px;
  border-radius: 10px;
  border-width: 2px;
  border-color: ${props => props.selected ? colors.primary : '#ddd'};
  justify-content: center;
  align-items: center;
  margin-left: ${spacing.sm}px;
`;

const SelectDot = styled.View`
  width: 10px;
  height: 10px;
  border-radius: 5px;
  background-color: ${colors.primary};
`;

const PaymentBar = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding-vertical: ${spacing.md}px;
  margin-top: ${spacing.sm}px;
`;

const PaymentText = styled.Text`
  font-size: 15px;
  font-weight: 500;
  color: ${colors.text};
  margin-left: ${spacing.sm}px;
  flex: 1;
`;

const ConfirmButton = styled.TouchableOpacity`
  background-color: #FFC107;
  height: 55px;
  border-radius: 30px;
  justify-content: center;
  align-items: center;
  margin-top: ${spacing.sm}px;
`;

const ConfirmButtonText = styled.Text`
  color: ${colors.secondary};
  font-size: 18px;
  font-weight: bold;
`;

const HomeScreen = () => {
  const navigation = useNavigation();
  const [isSelecting, setIsSelecting] = useState(false);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedCat, setSelectedCat] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState({ id: 'money', label: 'Dinheiro', icon: 'payments' });

  const toggleSelection = async () => {
    if (!isSelecting) {
      setLoading(true);
      setIsSelecting(true);
      try {
        const response = await api.passenger.getCategories(1);
        if (response.data && Array.isArray(response.data)) {
          setCategories(response.data);
          if (response.data.length > 0) setSelectedCat(response.data[0].id);
        }
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    } else {
      setIsSelecting(false);
    }
  };

  const handleConfirm = () => {
    const cat = categories.find(c => c.id === selectedCat);
    Alert.alert('Solicitando...', `Sua viagem de ${cat?.nome} foi solicitada!`);
  };

  return (
    <Container>
      <StatusBar barStyle="dark-content" backgroundColor="transparent" translucent />

      <TopBar>
        <IconButton onPress={() => isSelecting ? setIsSelecting(false) : null}>
          <Icon name={isSelecting ? "arrow-back" : "menu"} size={28} color={colors.secondary} />
        </IconButton>
        <IconButton>
          <Icon name="chat" size={24} color={colors.secondary} />
        </IconButton>
      </TopBar>

      <MapPlaceholder>
        <Icon name="map" size={150} color="#ddd" />
        <Text style={{ color: '#aaa', marginTop: 10, fontWeight: '500' }}>MAPA INTERATIVO</Text>
      </MapPlaceholder>

      <BottomSheet expanded={isSelecting}>
        <Handle />

        <ContentPadding>
          {!isSelecting ? (
            <>
              <Greeting>Olá, Passageiro!</Greeting>
              <Text style={{ color: colors.textSecondary }}>Onde você quer ir?</Text>

              <SearchButton activeOpacity={0.8} onPress={toggleSelection}>
                <Icon name="search" size={24} color={colors.primary} />
                <SearchButtonText>Informe seu destino...</SearchButtonText>
              </SearchButton>
            </>
          ) : (
            <>
              <Text style={{ fontSize: 16, fontWeight: 'bold', marginBottom: 10 }}>Escolha sua categoria</Text>

              {loading ? (
                <ActivityIndicator size="large" color={colors.primary} style={{ marginVertical: 30 }} />
              ) : (
                <ScrollView style={{ maxHeight: 250 }} showsVerticalScrollIndicator={false}>
                  {categories.map((cat) => (
                    <CategoryItem 
                      key={cat.id} 
                      selected={selectedCat === cat.id}
                      onPress={() => setSelectedCat(cat.id)}
                    >
                      <CategoryLeft>
                        <Icon name="directions-car" size={35} color={selectedCat === cat.id ? colors.primary : '#aaa'} />
                      </CategoryLeft>
                      <CategoryInfo>
                        <CategoryName>{cat.nome}</CategoryName>
                        <CategoryTime>Chegada em 4 min</CategoryTime>
                      </CategoryInfo>
                      <CategoryPrice>R$ {cat.tx_base || '14,90'}</CategoryPrice>
                      <SelectIndicator selected={selectedCat === cat.id}>
                        {selectedCat === cat.id && <SelectDot />}
                      </SelectIndicator>
                    </CategoryItem>
                  ))}
                </ScrollView>
              )}

              <PaymentBar onPress={() => Alert.alert('Pagamento', 'Opções de pagamento em breve!')}>
                <Icon name={paymentMethod.icon} size={24} color="#f39c12" />
                <PaymentText>{paymentMethod.label}</PaymentText>
                <Icon name="chevron-right" size={20} color="#ccc" />
              </PaymentBar>

              <ConfirmButton onPress={handleConfirm}>
                <ConfirmButtonText>CONFIRMAR {categories.find(c => c.id === selectedCat)?.nome.toUpperCase()}</ConfirmButtonText>
              </ConfirmButton>
            </>
          )}
        </ContentPadding>
      </BottomSheet>
    </Container>
  );
};

export default HomeScreen;
